type agreementNativeQuoteAddressSite struct {
	Root, Node, Parent, FirstNode int
	FirstKind                     string
	FirstLine                     graph.Span
	Opening, Unanchorable         bool
}

// A quote's first block and its complete visible opening line distinguish a
// title from later prose, even when a list supplies the surrounding column.
func agreementNativeQuoteAddressSites(body string, tree *agreementNativeProseAddressTree) []agreementNativeQuoteAddressSite {
	ctx := parser.NewContext()
	ctx.Set(agreementFootnoteTargetsKey, make(map[string]int))
	var unused []*extast.Footnote
	ctx.Set(agreementUnusedFootnoteNodesKey, &unused)
	ctx.Set(agreementNativeDefinitionSpansKey, make(map[ast.Node]agreementNativeDefinitionSpan))
	doc := agreementNativeOwnerGrammar.Parser().Parse(text.NewReader([]byte(body)), parser.WithContext(ctx))
	roots := []ast.Node{doc}
	for _, n := range unused {
		roots = append(roots, n)
	}
	var out []agreementNativeQuoteAddressSite
	for ri, root := range roots {
		at := 0
		var parents []int
		if err := ast.Walk(root, func(n ast.Node, entering bool) (ast.WalkStatus, error) {
			if !entering {
				parents = parents[:len(parents)-1]
				return ast.WalkContinue, nil
			}
			parent := -1
			if len(parents) > 0 {
				parent = parents[len(parents)-1]
			}
			current := at
			at++
			parents = append(parents, current)
			if n.Kind() != ast.KindBlockquote {
				return ast.WalkContinue, nil
			}
			site := agreementNativeQuoteAddressSite{Root: ri, Node: current, Parent: parent, FirstNode: -1}
			if first := n.FirstChild(); first != nil {
				site.FirstNode = current + 1
				site.FirstKind = first.Kind().String()
				if first.Kind() == ast.KindParagraph && first.Lines().Len() > 0 {
					line := first.Lines().At(0)
					site.FirstLine = graph.Span{Start: line.Start, Stop: line.Stop}
					shown := agreementNativeDiscardedAddressLines(body, &agreementNativeAddressPart{Fields: []agreementNativeAddressField{{Line: site.FirstLine}}}, tree)
					if len(shown) == 1 {
						line := "> " + strings.TrimRight(shown[0], "\r\n")
						site.Opening = render.IsCalloutOpening(line)
						site.Unanchorable = render.UnanchorableLine(line)
					}
				}
			}
			out = append(out, site)
			return ast.WalkContinue, nil
		}); err != nil {
			panic(err)
		}
	}
	return out
}

type agreementNativeQuoteAddressOwner struct{ Field, Node, List, Item, Quote int }

func agreementNativeQuoteAddressListOwner(sites []agreementNativeListAddressSite, position []int, owner *agreementNativeQuoteAddressOwner) bool {
	var lists, items []int
	for si, site := range sites {
		if site.Root != 0 {
			continue
		}
		if site.Node == position[1] && site.Kind == "List" {
			lists = append(lists, si)
		}
		if site.Node == position[2] && site.Kind == "ListItem" {
			items = append(items, si)
		}
	}
	if len(lists) != 1 || len(items) != 1 {
		return false
	}
	l, item := sites[lists[0]], sites[items[0]]
	if !l.Tight || l.Marker == 0 || l.Parent != 0 || item.Parent != l.Node || item.Offset <= 0 {
		return false
	}
	owner.List, owner.Item = lists[0], items[0]
	return true
}

// Every folded spelling belongs to ordinary text in one native quote.
// All physical occurrences and native container records stay bound.
func agreementNativeQuoteAddressOwners(part *agreementNativeAddressPart, tree *agreementNativeProseAddressTree, sites []agreementNativeListAddressSite, quotes []agreementNativeQuoteAddressSite) map[string][]agreementNativeQuoteAddressOwner {
	out := make(map[string][]agreementNativeQuoteAddressOwner)
	if !tree.Valid || len(tree.Trees) == 0 || len(tree.Unanchorable) != len(part.Fields) {
		return out
	}
	nodes := tree.Trees[0]
	var paths [][]string
	var positions [][]int
	var path []string
	var position []int
	for ni, n := range nodes {
		if n.Depth < 0 || n.Depth > len(path) {
			return out
		}
		path = append(slices.Clone(path[:n.Depth]), n.Kind)
		position = append(slices.Clone(position[:n.Depth]), ni)
		paths = append(paths, slices.Clone(path))
		positions = append(positions, slices.Clone(position))
	}
	groups := make(map[string][]int)
	for i, f := range part.Fields {
		groups[f.Folded] = append(groups[f.Folded], i)
	}
	for name, indices := range groups {
		var owners []agreementNativeQuoteAddressOwner
		valid := true
		for _, i := range indices {
			f := &part.Fields[i]
			if f.Owner != -1 || len(f.Nodes) != 0 || f.Code || f.Comment || tree.Unanchorable[i] {
				valid = false
			}
			for _, c := range tree.Code {
				if c.Span.Start < f.Token.Stop && f.Token.Start < c.Span.Stop {
					valid = false
				}
			}
			for _, c := range tree.Comments {
				if c.Start < f.Token.Stop && f.Token.Start < c.Stop {
					valid = false
				}
			}
			for _, d := range tree.Definitions {
				if d.Bounds.Span.Start < f.Token.Stop && f.Token.Start < d.Bounds.Span.Stop {
					valid = false
				}
			}
			owner := agreementNativeQuoteAddressOwner{Field: i, Node: -1, List: -1, Item: -1, Quote: -1}
			for ni, n := range nodes {
				plain := slices.Equal(paths[ni], []string{"Document", "Blockquote", "Paragraph", "Text"})
				listed := slices.Equal(paths[ni], []string{"Document", "List", "ListItem", "Blockquote", "Paragraph", "Text"})
				if (!plain && !listed) || n.Raw {
					continue
				}
				for _, span := range n.Text {
					if span.Start > f.Token.Start || f.Token.Stop > span.Stop {
						continue
					}
					if owner.Node >= 0 {
						valid = false
					}
					quoteNode := positions[ni][1]
					if listed {
						quoteNode = positions[ni][3]
					}
					var matched []int
					for qi, q := range quotes {
						if q.Root == 0 && q.Node == quoteNode {
							matched = append(matched, qi)
						}
					}
					if len(matched) != 1 {
						valid = false
						continue
					}
					q := quotes[matched[0]]
					paragraph := positions[ni][len(positions[ni])-2]
					parent := 0
					if listed {
						parent = positions[ni][2]
					}
					if q.Parent != parent || (q.Unanchorable && paragraph == q.FirstNode && f.Token.Start < q.FirstLine.Stop && q.FirstLine.Start < f.Token.Stop) {
						valid = false
					}
					if listed && !agreementNativeQuoteAddressListOwner(sites, positions[ni], &owner) {
						valid = false
						continue
					}
					owner.Node, owner.Quote = ni, matched[0]
				}
			}
			if owner.Node < 0 {
				valid = false
			}
			owners = append(owners, owner)
		}
		if valid {
			out[name] = owners
		}
	}
	return out
}

type agreementNativeQuoteAddressSource struct {
	Address             agreementNativeAddressSource
	Original, Projected agreementNativeProseAddressTree
	Lists, AfterLists   []agreementNativeListAddressSite
	Quotes, AfterQuotes []agreementNativeQuoteAddressSite
}

func agreementNativeQuoteAddressShapes(part *agreementNativeAddressPart, tree *agreementNativeProseAddressTree, sites []agreementNativeListAddressSite, quotes []agreementNativeQuoteAddressSite) []agreementNativeAddressField {
	owners := agreementNativeQuoteAddressOwners(part, tree, sites, quotes)
	out := slices.Clone(part.Fields)
	for i := range out {
		f := &out[i]
		if len(owners[f.Folded]) == 0 {
			continue
		}
		raw := []byte(f.Raw)
		for at := f.Token.Start - f.Line.Start + 1; at < f.Token.Stop-f.Line.Start; at++ {
			raw[at] = '?'
		}
		f.Raw, f.Name, f.Folded = string(raw), "?", "?"
	}
	return out
}

// Same-width private tail names preserve every other byte and every native
// node, unused declaration, check field, code/comment range and physical role.
func agreementNativeQuoteAddressReading(body string) agreementNativeQuoteAddressSource {
	r := agreementNativeQuoteAddressSource{Address: agreementNativeAddressSource{Original: agreementNativeAddressPartReading(body)}}
	r.Original = agreementNativeProseAddressTreeReading(body, r.Address.Original.Fields)
	r.Lists = agreementNativeListAddressSites(body)
	r.Quotes = agreementNativeQuoteAddressSites(body, &r.Original)
	owners := agreementNativeQuoteAddressOwners(&r.Address.Original, &r.Original, r.Lists, r.Quotes)
	occupied := make(map[string]bool)
	for _, name := range r.Address.Original.Names {
		if strings.ContainsAny(name, "|#]\r\n") || strings.HasSuffix(name, "\\") {
			return r
		}
		occupied[name] = true
	}
	changed := make(map[string]string)
	private := []byte(body)
	for i := range r.Address.Original.Fields {
		f := &r.Address.Original.Fields[i]
		if len(owners[f.Folded]) == 0 {
			continue
		}
		name := changed[f.Folded]
		if name == "" {
			for _, ch := range []string{"q", "z", "v", "x", "w"} {
				candidate := "^" + strings.Repeat(ch, len(f.Name)-1)
				if !occupied[candidate] {
					name = candidate
					break
				}
			}
			if name == "" {
				return r
			}
			changed[f.Folded], occupied[name] = name, true
			r.Address.Changes = append(r.Address.Changes, agreementNativeAddressChange{Old: f.Folded, New: name})
		}
		if len(name) != f.Token.Stop-f.Token.Start {
			return r
		}
		copy(private[f.Token.Start:f.Token.Stop], name)
	}
	if len(r.Address.Changes) == 0 {
		return r
	}
	r.Address.Body = string(private)
	r.Address.Projected = agreementNativeAddressPartReading(r.Address.Body)
	r.Projected = agreementNativeProseAddressTreeReading(r.Address.Body, r.Address.Projected.Fields)
	r.AfterLists = agreementNativeListAddressSites(r.Address.Body)
	r.AfterQuotes = agreementNativeQuoteAddressSites(r.Address.Body, &r.Projected)
	r.Address.Shapes, r.Address.AfterShapes = agreementNativeQuoteAddressShapes(&r.Address.Original, &r.Original, r.Lists, r.Quotes), agreementNativeQuoteAddressShapes(&r.Address.Projected, &r.Projected, r.AfterLists, r.AfterQuotes)
	r.Address.Valid = cmp.Equal(r.Original, r.Projected) && cmp.Equal(r.Lists, r.AfterLists) && cmp.Equal(r.Quotes, r.AfterQuotes) && cmp.Equal(r.Address.Shapes, r.Address.AfterShapes) && cmp.Equal(r.Address.Original.Native, r.Address.Projected.Native) && cmp.Equal(r.Address.Original.Check, r.Address.Projected.Check) && slices.Equal(r.Address.Original.Check.Targets, judge.LinkTargets(body)) && slices.Equal(r.Address.Projected.Check.Targets, judge.LinkTargets(r.Address.Body))
	return r
}

type agreementNativeQuoteAddressPayload struct {
	Address      agreementNativeAddressPayload
	NativeSource agreementNativeQuoteAddressSource
	Owners       map[string][]agreementNativeQuoteAddressOwner
}

// An ordinary quote tail has address authority on all three faces. Its
// private name must reproduce the whole public ledger without borrowing any
// unrelated name, cut, ordered page member or signed disagreement.
func agreementNativeQuoteAddressEvidence(p *agreementNativeQuoteAddressPayload) bool {
	s := &p.Address.Source
	a, w := agreementHTML{Blocks: p.Address.Blocks}, agreementHTML{Blocks: p.Address.WitnessBlocks}
	if !s.Valid || len(s.Changes) == 0 || len(s.Original.Fields) != len(s.Projected.Fields) || !cmp.Equal(*s, p.NativeSource.Address) || !cmp.Equal(p.Owners, agreementNativeQuoteAddressOwners(&s.Original, &p.NativeSource.Original, p.NativeSource.Lists, p.NativeSource.Quotes)) || len(p.Owners) != len(s.Changes) || !cmp.Equal(p.Address.Names, agreementNativeAddressNames(s, &a, &w)) || len(p.Address.Original) != len(p.Address.Names) || len(p.Address.Witness) != len(p.Address.Names) || !cmp.Equal(p.Address.Signatures, agreementNativeAddressSignatures(p.Address.Original)) {
		return false
	}
	selected := make(map[string]string)
	nextOwners := agreementNativeQuoteAddressOwners(&s.Projected, &p.NativeSource.Projected, p.NativeSource.AfterLists, p.NativeSource.AfterQuotes)
	if len(nextOwners) != len(p.Owners) {
		return false
	}
	visible := false
	for _, c := range s.Changes {
		old, ok := p.Address.Original[c.Old]
		next, has := p.Address.Witness[c.New]
		if !ok || !has || len(p.Owners[c.Old]) == 0 || !cmp.Equal(p.Owners[c.Old], nextOwners[c.New]) || p.Address.Original[c.New] != (agreementNativeAddressReceipt{}) || p.Address.Witness[c.Old] != (agreementNativeAddressReceipt{}) || old.Page != next.Page || old.Judge != next.Judge || old.Found != next.Found {
			return false
		}
		selected[c.Old], selected[c.New] = c.New, c.New
		if old.Page != old.Judge || old.Page != old.Found {
			visible = true
		}
		if old.Found {
			paired := false
			for _, o := range p.Owners[c.Old] {
				f, g := &s.Original.Fields[o.Field], &s.Projected.Fields[o.Field]
				if agreementNativeReservationLine(old.Cut, f.Raw) && agreementNativeReservationLine(next.Cut, g.Raw) {
					paired = true
				}
			}
			if !paired {
				return false
			}
		}
	}
	if !visible {
		return false
	}
	expected := slices.Clone(p.Address.Blocks)
	for i, name := range expected {
		if renamed := selected[name]; renamed != "" {
			expected[i] = renamed
		}
	}
	if !cmp.Equal(expected, p.Address.WitnessBlocks) {
		return false
	}
	for _, name := range p.Address.Names {
		before, ok := p.Address.Original[name]
		after, has := p.Address.Witness[name]
		cut, found := render.Excerpt(p.Address.Body, name)
		wcut, wfound := render.Excerpt(s.Body, name)
		if !ok || !has || before.Page != slices.Contains(p.Address.Blocks, name) || after.Page != slices.Contains(p.Address.WitnessBlocks, name) || before.Cut != cut || before.Found != found || after.Cut != wcut || after.Found != wfound || (selected[name] == "" && before != after) {
			return false
		}
	}
	return true
}
func agreementNativeQuoteAddressBudget(t *testing.T, body string, a *agreementHTML, fs []agreementFailure) agreementNativeQuoteAddressPayload {
	t.Helper()
	source := agreementNativeQuoteAddressReading(body)
	s := &source.Address
	if !s.Valid {
		return agreementNativeQuoteAddressPayload{}
	}
	_, w := agreementIsolatedPage(t, agreementCase{Body: s.Body})
	names := agreementNativeAddressNames(s, a, &w)
	before, after := agreementNativeAddressPublic(t, body, a, names), agreementNativeAddressPublic(t, s.Body, &w, names)
	p := agreementNativeQuoteAddressPayload{Address: agreementNativeAddressPayload{Body: body, Source: *s, Names: names, Blocks: slices.Clone(a.Blocks), WitnessBlocks: slices.Clone(w.Blocks), Original: before, Witness: after, Signatures: agreementNativeAddressSignatures(before)}, NativeSource: source, Owners: agreementNativeQuoteAddressOwners(&s.Original, &source.Original, source.Lists, source.Quotes)}
	if !agreementNativeQuoteAddressEvidence(&p) || !cmp.Equal(p.Address.Signatures, agreementNativeAddressCurrent(fs)) {
		return agreementNativeQuoteAddressPayload{}
	}
	return p
}
func agreementNativeQuoteAddressDifference(c agreementCase, f *agreementFailure, a *agreementHTML, fs []agreementFailure, p *agreementNativeQuoteAddressPayload) (kind, authority, wrong string) {
	if c.Body != p.Address.Body || c.Title != "" || len(c.Companions) != 0 || f.Property != "P3" || f.Identity != "block-three-way" || f.Tuple != (agreementCitation{}) || f.Multiplicity != 1 || p.Address.Signatures[agreementSignature(f)] != 1 || len(p.Owners[f.Fragment]) == 0 {
		return "", "", ""
	}
	if !cmp.Equal(p.NativeSource, agreementNativeQuoteAddressReading(c.Body)) || !cmp.Equal(p.Address.Blocks, a.Blocks) || !cmp.Equal(p.Address.Signatures, agreementNativeAddressCurrent(fs)) || !agreementNativeQuoteAddressEvidence(p) {
		return "", "", ""
	}
	r := p.Address.Original[f.Fragment]
	var faces []string
	if !r.Page {
		faces = append(faces, "page")
	}
	if !r.Judge {
		faces = append(faces, "judge")
	}
	if !r.Found {
		faces = append(faces, "excerpt")
	}
	if len(faces) == 0 {
		return "", "", ""
	}
	return "debt", "#1011 stage 5", strings.Join(faces, "+")
}

