			if len(s.Original.Trees) != 1 || len(s.Original.Trees[0]) != 7 || len(s.Lists) != 2 || len(s.Quotes) != 1 || len(s.Address.Original.Fields) != 1 || len(s.Original.Trees[0][6].Text) != 1 {
				t.Fatal("quote owner drift lacks complete declared shape")
			}
			tc.change(&s.Address.Original, &s.Original, &s.Lists, &s.Quotes)
			if diff := cmp.Diff(map[string][]agreementNativeQuoteAddressOwner{}, agreementNativeQuoteAddressOwners(&s.Address.Original, &s.Original, s.Lists, s.Quotes)); diff != "" {
				t.Fatalf("caught: complete quote owner eligibility (-want +got):\n%s", diff)
			}
