		t.Parallel()
		s := agreementNativeQuoteAddressReading(agreementNativeQuoteAddressControls()[154].Body)
		want := map[string][]agreementNativeQuoteAddressOwner{"^a": {{Field: 0, Node: 4, List: -1, Item: -1, Quote: 0}, {Field: 1, Node: 6, List: -1, Item: -1, Quote: 0}}}
